import test from 'node:test';
import assert from 'node:assert/strict';
import { roundCents, formatEuros, parseEuros, RATES, convert, formatMoney } from '../src/money.js';

test('roundCents halves to even (banker\'s rounding)', () => {
  assert.equal(roundCents(124.5), 124);
  assert.equal(roundCents(125.5), 126);
  assert.equal(roundCents(2.4), 2);
  assert.equal(roundCents(-0.5), 0);
});

test('formatEuros formats cents as euros', () => {
  assert.equal(formatEuros(123456), '€1,234.56');
  assert.equal(formatEuros(-5), '-€0.05');
});

test('parseEuros parses euro strings', () => {
  const result = parseEuros('12.5');
  assert.equal(result.ok, true);
  assert.equal(result.value, 1250);
});

test('RATES has EUR, USD, GBP', () => {
  assert.equal(RATES.EUR, 1);
  assert.equal(RATES.USD, 1.085);
  assert.equal(RATES.GBP, 0.8425);
});

test('convert returns ok for valid currency', () => {
  const result = convert(100, 'EUR');
  assert.equal(result.ok, true);
  assert.equal(typeof result.value, 'number');
});

test('convert returns UNKNOWN_CURRENCY for invalid currency', () => {
  const result = convert(100, 'JPY');
  assert.deepEqual(result, { ok: false, error: 'UNKNOWN_CURRENCY' });
});

test('convert EUR to EUR is identity', () => {
  const result = convert(100, 'EUR');
  assert.equal(result.value, 100);
});

test('convert EUR to USD applies rate', () => {
  const result = convert(100, 'USD');
  assert.equal(result.ok, true);
  assert(result.value > 100);
});

test('convert EUR to GBP applies rate', () => {
  const result = convert(100, 'GBP');
  assert.equal(result.ok, true);
  assert(result.value < 100);
});

test('convert 1 EUR to USD is approximately 108.5 cents', () => {
  const result = convert(100, 'USD');
  assert.equal(result.value, 109);
});

test('convert 1 EUR to GBP is approximately 84.25 cents', () => {
  const result = convert(100, 'GBP');
  assert.equal(result.value, 84);
});

test('convert rounds to nearest cent', () => {
  const result = convert(123, 'USD');
  assert.equal(result.ok, true);
  assert(Number.isInteger(result.value));
});

test('convert handles large amounts', () => {
  const result = convert(100000, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 108500);
});

test('convert handles zero', () => {
  const result = convert(0, 'USD');
  assert.equal(result.value, 0);
});

test('convert handles negative amounts', () => {
  const result = convert(-100, 'USD');
  assert.equal(result.ok, true);
  assert(result.value < 0);
});

test('formatMoney formats EUR with euro sign', () => {
  const result = formatMoney(123456, 'EUR');
  assert.equal(result, '€1,234.56');
});

test('formatMoney formats USD with dollar sign', () => {
  const result = formatMoney(123456, 'USD');
  assert.equal(result, '$1,234.56');
});

test('formatMoney formats GBP with pound sign', () => {
  const result = formatMoney(123456, 'GBP');
  assert.equal(result, '£1,234.56');
});

test('formatMoney handles negative amounts', () => {
  const result = formatMoney(-123456, 'USD');
  assert.equal(result, '-$1,234.56');
});

test('formatMoney handles small amounts', () => {
  const result = formatMoney(5, 'USD');
  assert.equal(result, '$0.05');
});

test('formatMoney handles zero', () => {
  const result = formatMoney(0, 'USD');
  assert.equal(result, '$0.00');
});

test('formatMoney uses thousands separator', () => {
  const result = formatMoney(1234567, 'USD');
  assert.equal(result, '$12,345.67');
});

test('formatMoney uses 2 decimal places', () => {
  const result = formatMoney(1234, 'USD');
  assert.ok(result.includes('.34'));
});

test('formatMoney pads cents with leading zero', () => {
  const result = formatMoney(505, 'USD');
  assert.equal(result, '$5.05');
});

test('convert and formatMoney work together for EUR to USD', () => {
  const euroCents = 100;
  const usdResult = convert(euroCents, 'USD');
  const formatted = formatMoney(usdResult.value, 'USD');
  assert.equal(formatted, '$1.09');
});

test('convert and formatMoney work together for EUR to GBP', () => {
  const euroCents = 100;
  const gbpResult = convert(euroCents, 'GBP');
  const formatted = formatMoney(gbpResult.value, 'GBP');
  assert.equal(formatted, '£0.84');
});

test('convert multiple EUR to USD', () => {
  const usd1 = convert(100, 'USD').value;
  const usd2 = convert(200, 'USD').value;
  assert.equal(usd2, usd1 * 2);
});

test('convert invoice total to USD', () => {
  const eurCents = 58500;
  const result = convert(eurCents, 'USD');
  const formatted = formatMoney(result.value, 'USD');
  assert.ok(formatted.startsWith('$'));
  assert.ok(formatted.includes('.'));
});

test('formatMoney with large negative amount', () => {
  const result = formatMoney(-1234567, 'GBP');
  assert.equal(result, '-£12,345.67');
});

test('RATES object is object type', () => {
  assert.equal(typeof RATES, 'object');
});

test('convert handles case sensitivity', () => {
  const result = convert(100, 'eur');
  assert.equal(result.ok, false);
});

test('convert with all three currencies', () => {
  const eur = convert(100, 'EUR').value;
  const usd = convert(100, 'USD').value;
  const gbp = convert(100, 'GBP').value;
  assert.equal(eur, 100);
  assert(usd > eur);
  assert(gbp < eur);
});

test('formatMoney with all three currencies', () => {
  const amount = 100;
  const eur = formatMoney(amount, 'EUR');
  const usd = formatMoney(amount, 'USD');
  const gbp = formatMoney(amount, 'GBP');
  assert.ok(eur.includes('€'));
  assert.ok(usd.includes('$'));
  assert.ok(gbp.includes('£'));
});

test('convert maintains precision through rounding', () => {
  const result1 = convert(1, 'USD');
  const result2 = convert(1, 'USD');
  assert.equal(result1.value, result2.value);
});

test('convert fractional amounts round correctly', () => {
  const result = convert(333, 'USD');
  assert.equal(result.ok, true);
  assert(Number.isInteger(result.value));
});

